// ---------- Satın Alma > Kayıtlar (Hurda + Çapak + Granül, tek listede, en yeni üstte) ----------
var SA_KAYITLAR_FILTRE = { baslangic:'', bitis:'', tur:'', cins:'' };
function renderSatinAlmaKayitlar(c){
  var turEtiket = {hurda:'Hurda', capak:'Çapak', granul:'Granül'};
  var silFonksiyonu = {hurda:'deleteHurdaGirisi', capak:'deleteCapakGirisi', granul:'deleteGranulGirisi'};
  var hepsiFiltresiz = [];
  ['hurda','capak','granul'].forEach(function(tur){
    var kat = SATIN_ALIM_KATEGORILERI[tur];
    (STATE.merkeziSatinAlmalar[kat.stateKey]||[]).forEach(function(g){
      hepsiFiltresiz.push(Object.assign({tur:tur}, g));
    });
  });
  hepsiFiltresiz.sort(function(a,b){ return b.tarih.localeCompare(a.tarih) || (b.olusturmaZamani||'').localeCompare(a.olusturmaZamani||''); });

  var f = SA_KAYITLAR_FILTRE;
  var hepsi = hepsiFiltresiz.filter(function(g){
    if(f.baslangic && g.tarih < f.baslangic) return false;
    if(f.bitis && g.tarih > f.bitis) return false;
    if(f.tur && g.tur !== f.tur) return false;
    if(f.cins && g.urun !== f.cins) return false;
    return true;
  });
  // Cins seçenekleri: seçili türe göre daralır (tür seçilmemişse hepsi birlikte gösterilir).
  var cinsSecenekleri = Array.from(new Set(
    hepsiFiltresiz.filter(function(g){ return !f.tur || g.tur===f.tur; }).map(function(g){ return g.urun; })
  )).sort(function(a,b){ return a.localeCompare(b,'tr-TR'); });

  var iscilikListe = (STATE.merkeziSatinAlmalar.iscilikCapakGirisleri||[]).slice()
    .sort(function(a,b){ return b.tarih.localeCompare(a.tarih) || (b.olusturmaZamani||'').localeCompare(a.olusturmaZamani||''); });

  c.innerHTML =
    '<div class="toolbar">'+
      '<div class="field"><label>Başlangıç</label><input type="date" id="sak_baslangic" value="'+f.baslangic+'"></div>'+
      '<div class="field"><label>Bitiş</label><input type="date" id="sak_bitis" value="'+f.bitis+'"></div>'+
      '<div class="field"><label>Tür</label><select id="sak_tur">'+
        '<option value="">Tümü</option>'+
        '<option value="hurda"'+(f.tur==='hurda'?' selected':'')+'>Hurda</option>'+
        '<option value="capak"'+(f.tur==='capak'?' selected':'')+'>Çapak</option>'+
        '<option value="granul"'+(f.tur==='granul'?' selected':'')+'>Granül</option>'+
      '</select></div>'+
      '<div class="field"><label>Cins</label><select id="sak_cins">'+
        '<option value="">Tümü</option>'+
        cinsSecenekleri.map(function(u){ return '<option value="'+escapeHtml(u)+'"'+(f.cins===u?' selected':'')+'>'+escapeHtml(u)+'</option>'; }).join('')+
      '</select></div>'+
      '<button class="btn ghost" id="sak_temizle">Filtreleri Temizle</button>'+
    '</div>'+
    (hepsiFiltresiz.length===0 ? '<div class="empty"><b>Henüz (parayla alınan) satın alma kaydı yok</b></div>' :
      hepsi.length===0 ? '<div class="empty"><b>Bu filtrelerle eşleşen kayıt yok</b></div>' :
      '<div class="card"><table><thead><tr>'+
          '<th>Tarih</th><th>Tür</th><th>Cins</th><th>Miktar (kg)</th><th>Fire %</th><th>Fire Düşülmüş (kg)</th><th>Fiyat (TL/kg)</th><th>Nakliye (TL)</th><th>Toplam Maliyet</th><th>Maliyet (TL/kg)</th><th>Not</th><th>Giren</th><th></th>'+
        '</tr></thead><tbody>'+
        hepsi.map(function(g){
          var fireDestekli = SATIN_ALIM_KATEGORILERI[g.tur].fireDestekli;
          var fkg = fireDestekli ? fireliKg(g) : (Number(g.kg)||0);
          var maliyet = girisMaliyetiKgBasi(g);
          return '<tr><td class="txt">'+escapeHtml(tarihGoster(g.tarih))+'</td>'+
            '<td class="txt"><span class="tag">'+turEtiket[g.tur]+'</span></td>'+
            '<td class="txt"><span class="tag '+tagClassFor(g.urun)+'">'+escapeHtml(g.urun)+'</span></td>'+
            '<td>'+fmtKg(g.kg)+'</td>'+
            '<td>'+(fireDestekli && Number(g.fireOrani) ? fmt(g.fireOrani)+'%' : '—')+'</td>'+
            '<td>'+(fireDestekli ? fmtKg(fkg) : '—')+'</td>'+
            '<td>'+fmt(g.fiyat)+'</td>'+
            '<td>'+(Number(g.nakliyeUcreti) ? fmt(g.nakliyeUcreti)+' TL' : '—')+'</td>'+
            '<td>'+fmt(girisNakliyeliToplamMaliyet(g))+' TL</td>'+
            '<td>'+fmt(maliyet)+'</td>'+
            '<td class="txt" style="max-width:150px; white-space:pre-wrap;">'+(g.notlar?escapeHtml(g.notlar):'<span style="color:var(--muted);">—</span>')+'</td>'+
            '<td class="txt">'+escapeHtml(g.girenAd||'')+'</td>'+
            '<td style="white-space:nowrap;">'+(canMutate()?('<button class="btn ghost small" data-sa-edit="'+g.id+'" data-sa-tur="'+g.tur+'">Düzenle</button> <button class="btn danger small" data-sa-del="'+g.id+'" data-sa-tur="'+g.tur+'">Sil</button>'):'')+'</td></tr>';
        }).join('')+
      '</tbody></table></div>')+
    '<div class="section-title" style="display:flex; align-items:center; justify-content:space-between;">'+
      '<span>Çapak İşçiliği <span style="font-weight:400; color:var(--muted); font-size:12px;">(bedelsiz — normal çapak/granül stoğundan AYRI)</span></span>'+
      (iscilikListe.length>0 ? '<button class="btn ghost small" id="icg_pdf_btn">PDF Olarak Dışa Aktar</button>' : '')+
    '</div>'+
    (iscilikListe.length===0 ? '<div class="empty"><b>Henüz İşçilik Çapak kaydı yok</b></div>' :
      '<div class="card"><table><thead><tr><th>Tarih</th><th>Çapak Cinsi</th><th>Miktar (kg)</th><th>Not</th><th>Giren</th><th></th></tr></thead><tbody>'+
        iscilikListe.map(function(g){
          return '<tr><td class="txt">'+escapeHtml(tarihGoster(g.tarih))+'</td>'+
            '<td class="txt"><span class="tag '+tagClassFor(g.urun)+'">'+escapeHtml(g.urun)+'</span></td>'+
            '<td>'+fmtKg(g.kg)+'</td>'+
            '<td class="txt" style="max-width:220px; white-space:pre-wrap;">'+(g.notlar?escapeHtml(g.notlar):'<span style="color:var(--muted);">—</span>')+'</td>'+
            '<td class="txt">'+escapeHtml(g.girenAd||'')+'</td>'+
            '<td style="white-space:nowrap;">'+(canMutate()?('<button class="btn ghost small" data-icg-edit="'+g.id+'">Düzenle</button> <button class="btn danger small" data-icg-del="'+g.id+'">Sil</button>'):'')+'</td></tr>';
        }).join('')+
      '</tbody></table></div>');

  document.getElementById('sak_baslangic').addEventListener('change', function(ev){ SA_KAYITLAR_FILTRE.baslangic = ev.target.value; renderSatinAlmaKayitlar(c); });
  document.getElementById('sak_bitis').addEventListener('change', function(ev){ SA_KAYITLAR_FILTRE.bitis = ev.target.value; renderSatinAlmaKayitlar(c); });
  document.getElementById('sak_tur').addEventListener('change', function(ev){ SA_KAYITLAR_FILTRE.tur = ev.target.value; SA_KAYITLAR_FILTRE.cins = ''; renderSatinAlmaKayitlar(c); });
  document.getElementById('sak_cins').addEventListener('change', function(ev){ SA_KAYITLAR_FILTRE.cins = ev.target.value; renderSatinAlmaKayitlar(c); });
  document.getElementById('sak_temizle').addEventListener('click', function(){ SA_KAYITLAR_FILTRE = { baslangic:'', bitis:'', tur:'', cins:'' }; renderSatinAlmaKayitlar(c); });

  Array.prototype.forEach.call(c.querySelectorAll('[data-sa-edit]'), function(b){
    b.addEventListener('click', function(){
      var tur = b.dataset.saTur;
      var kat = SATIN_ALIM_KATEGORILERI[tur];
      var kayit = (STATE.merkeziSatinAlmalar[kat.stateKey]||[]).find(function(x){ return x.id === b.dataset.saEdit; });
      if(!kayit) return;
      activeTab = 'panel'; renderTabs();
      renderSatinAlmaEkrani(document.getElementById('content'), Object.assign({_tur: tur}, kayit));
    });
  });
  Array.prototype.forEach.call(c.querySelectorAll('[data-sa-del]'), function(b){
    b.addEventListener('click', function(){
      var tur = b.dataset.saTur;
      var kat = SATIN_ALIM_KATEGORILERI[tur];
      var oge = (STATE.merkeziSatinAlmalar[kat.stateKey]||[]).find(function(x){ return x.id === b.dataset.saDel; });
      showConfirm('Bu satın alma kaydını silmek istediğinize emin misiniz?', 'Sil', function(){
        var aciklama = 'Satın alma kaydı silme: '+(oge?(turEtiket[tur]+' — '+oge.urun+', '+fmtKg(oge.kg)+' kg'):'');
        mutasyonCagirUretim(silFonksiyonu[tur], ['merkezi', b.dataset.saDel], aciklama, 'Satın Alma', false, function(liste, kuyruga){
          if(kuyruga) return;
          STATE.merkeziSatinAlmalar[kat.stateKey] = liste;
          renderSatinAlmaKayitlar(document.getElementById('content'));
        });
      });
    });
  });

  Array.prototype.forEach.call(c.querySelectorAll('[data-icg-edit]'), function(b){
    b.addEventListener('click', function(){
      var kayit = (STATE.merkeziSatinAlmalar.iscilikCapakGirisleri||[]).find(function(x){ return x.id === b.dataset.icgEdit; });
      if(!kayit) return;
      activeTab = 'panel'; renderTabs();
      renderSatinAlmaEkrani(document.getElementById('content'), Object.assign({_tur: 'iscilikCapak'}, kayit));
    });
  });
  Array.prototype.forEach.call(c.querySelectorAll('[data-icg-del]'), function(b){
    b.addEventListener('click', function(){
      var oge = (STATE.merkeziSatinAlmalar.iscilikCapakGirisleri||[]).find(function(x){ return x.id === b.dataset.icgDel; });
      showConfirm('Bu İşçilik Çapak kaydını silmek istediğinize emin misiniz?', 'Sil', function(){
        var aciklama = 'İşçilik Çapak kaydı silme: '+(oge?oge.urun+', '+fmtKg(oge.kg)+' kg':'');
        mutasyonCagirUretim('deleteIscilikCapakGirisi', ['merkezi', b.dataset.icgDel], aciklama, 'Satın Alma', false, function(liste, kuyruga){
          if(kuyruga) return;
          STATE.merkeziSatinAlmalar.iscilikCapakGirisleri = liste;
          renderSatinAlmaKayitlar(document.getElementById('content'));
        });
      });
    });
  });

  (document.getElementById('icg_pdf_btn')||{addEventListener:function(){}}).addEventListener('click', function(){
    pdfDisaAktarPenceresiAc({
      baslik: 'Çapak İşçiliği Kayıtları',
      tarihAlani: 'tarih',
      sutunlar: [{key:'tarih',label:'Tarih'},{key:'urun',label:'Çapak Cinsi'},{key:'kg',label:'Miktar (kg)'},{key:'notlar',label:'Not'},{key:'girenAd',label:'Giren'}],
      kayitlarGetir: function(){ return iscilikListe; },
      satirDegeri: function(g, key){ return key==='kg' ? fmtKg(g.kg) : (g[key]||''); },
      ozetSatirlari: function(kayitlar){
        var toplamKg = kayitlar.reduce(function(s,g){ return s+(Number(g.kg)||0); },0);
        return [{etiket:'Toplam Kayıt', deger:String(kayitlar.length)}, {etiket:'Toplam Kg', deger:fmtKg(toplamKg)+' kg'}];
      }
    });
  });
}

// ---------- Satın Alma > Aylık Rapor (Hurda/Çapak/Granül, seçilen ay için özet) ----------
function renderSatinAlmaAylikRapor(c){
  var month = window.__saSelMonth || todayStr().slice(0,7);
  c.innerHTML = '<div class="toolbar"><div class="field"><label>Ay Seç</label><input type="month" id="sa_ay_sel" value="'+month+'"></div></div><div id="sa_ay_content"></div>';
  document.getElementById('sa_ay_sel').addEventListener('change', function(ev){ window.__saSelMonth = ev.target.value; renderSatinAlmaAylikIcerik(ev.target.value); });
  renderSatinAlmaAylikIcerik(month);
}

function renderSatinAlmaAylikIcerik(month){
  var box = document.getElementById('sa_ay_content'); if(!box) return;
  function ozetHesapla(liste, fireDestekli){
    var buAy = (liste||[]).filter(function(g){ return g.tarih.slice(0,7)===month; });
    var toplamKg = buAy.reduce(function(s,g){ return s+(Number(g.kg)||0); },0);
    var toplamUrunTutari = buAy.reduce(function(s,g){ return s+girisToplamTutar(g); },0);
    var toplamNakliye = buAy.reduce(function(s,g){ return s+(Number(g.nakliyeUcreti)||0); },0);
    var toplamMaliyetNakliyeli = toplamUrunTutari + toplamNakliye;
    var toplamFireliKg = fireDestekli ? buAy.reduce(function(s,g){ return s+fireliKg(g); },0) : toplamKg;
    return {
      adet: buAy.length, toplamKg: toplamKg, toplamUrunTutari: toplamUrunTutari, toplamNakliye: toplamNakliye,
      toplamMaliyetNakliyeli: toplamMaliyetNakliyeli, toplamFireliKg: toplamFireliKg,
      ortFiyat: toplamKg ? toplamUrunTutari/toplamKg : 0,
      ortMaliyet: toplamFireliKg ? toplamMaliyetNakliyeli/toplamFireliKg : 0
    };
  }
  var basliklar = STATE.merkeziCinsler.cinsBasliklari;
  var kategoriler = [
    { key:'hurda', baslik: cinsAdiKisa(basliklar.hurda), ozet: ozetHesapla(STATE.merkeziSatinAlmalar.hurdaGirisleri, true), fireDestekli:true },
    { key:'capak', baslik: cinsAdiKisa(basliklar.capak), ozet: ozetHesapla(STATE.merkeziSatinAlmalar.capakGirisleri, true), fireDestekli:true },
    { key:'granul', baslik: cinsAdiKisa(basliklar.granul), ozet: ozetHesapla(STATE.merkeziSatinAlmalar.granulGirisleri, false), fireDestekli:false }
  ];
  box.innerHTML = '<div class="callout">Seçilen <b class="mono">'+escapeHtml(ayGoster(month))+'</b> ayı içinde girilen satın alma kayıtlarının özetidir. "Toplam Maliyet" ve "Ort. Maliyet" değerleri nakliye ücretini de içerir.</div>'+
    kategoriler.map(function(k){
      var o = k.ozet;
      return '<div class="section-title" style="margin-top:22px;">'+escapeHtml(k.baslik)+'</div>'+
        '<div class="grid grid-3">'+
          '<div class="card"><h3>Toplam Alınan</h3><div class="stat">'+fmtKg(o.toplamKg)+'<small>kg</small></div></div>'+
          '<div class="card"><h3>Toplam Ürün Tutarı</h3><div class="stat">'+(o.toplamKg?fmt(o.toplamUrunTutari):'—')+'<small>'+(o.toplamKg?'TL':'—')+'</small></div></div>'+
          '<div class="card"><h3>Toplam Nakliye</h3><div class="stat">'+(o.toplamNakliye?fmt(o.toplamNakliye):'—')+'<small>'+(o.toplamNakliye?'TL':'—')+'</small></div></div>'+
        '</div>'+
        '<div class="grid grid-3" style="margin-top:10px;">'+
          (k.fireDestekli ? '<div class="card"><h3>Fire Düşülmüş Miktar</h3><div class="stat">'+fmtKg(o.toplamFireliKg)+'<small>kg</small></div></div>' : '<div class="card"><h3>Ort. Fiyat</h3><div class="stat">'+(o.toplamKg?fmt(o.ortFiyat):'—')+'<small>'+(o.toplamKg?'TL/kg':'—')+'</small></div></div>')+
          '<div class="card"><h3>Ort. Maliyet (Nakliye'+(k.fireDestekli?'+Fire':'')+' Dahil)</h3><div class="stat">'+(o.toplamFireliKg?fmt(o.ortMaliyet):'—')+'<small>'+(o.toplamFireliKg?'TL/kg':'—')+'</small></div></div>'+
          '<div class="card"><h3>Kayıt Sayısı</h3><div class="stat">'+o.adet+'<small>adet</small></div></div>'+
        '</div>';
    }).join('');
}

// ============================================================
// "DİĞER BİRİM" (örn. Şişirme Birimi) — BİDON ÜRETİMİ formu. Adet bazlı üretim + adet bazlı fire
// + ürün gramajına göre otomatik hesaplanan hammadde tüketimi. Granül'ün elektrik/işçilik/Agromel/
// Çapak Cinsi mantığıyla HİÇ ilgisi yok — kasıtlı olarak çok daha basit bir model.
// Veri modeli (bd.entries, mevcut alanlar yeniden kullanılıyor): kg = Üretilen Adet,
// fireAdedi = Fire Adedi (adet, YÜZDE DEĞİL), kullanilanCapak = otomatik hesaplanan kg
// (Üretilen Adet + Fire Adedi) × Ürün Gramajı. capakCinsi kullanılmaz (boş bırakılır).
// ============================================================
function renderBidonUretimFormHTML(editEntry){
  var isEdit = !!editEntry;
  var veri = STATE.birimVeri;
  var gruplar = tumUrunGruplariBirlesik(veri);
  if(gruplar.length===0){
    return '<div class="callout warn">Henüz tanımlı bidon tipi yok. Kayıt ekleyebilmek için önce <a id="bu_go_param" style="color:var(--amber); cursor:pointer;">Parametreler</a> sayfasından en az bir tane ekleyin (gramajıyla birlikte).</div>';
  }
  // Ürünler, tanımlı oldukları sekmeye göre (çekirdek sekmeler + her ek kategori) optgroup'lara
  // ayrılarak gösterilir — kullanıcı hangi bidon ailesinden seçtiğini kolayca görebilsin diye.
  var options = gruplar.map(function(g){
    return '<optgroup label="'+escapeHtml(g.baslik)+'">'+
      g.ogeler.map(function(p){ return '<option value="'+escapeHtml(p.ad)+'" data-gramaj="'+(Number(p.gramaj)||0)+'">'+escapeHtml(p.ad)+'</option>'; }).join('')+
    '</optgroup>';
  }).join('');
  var hammaddeler = veri.hammaddeCinsleri || [];
  var granulCinsleri = STATE.merkeziCinsler.urunler || [];
  var hammaddeOptions = '<option value="">— seçilmedi —</option>'+
    hammaddeler.map(function(h){ return '<option value="'+escapeHtml(h.ad)+'"'+(isEdit&&editEntry.girdiTuru!=='granul'&&editEntry.hammaddeCinsi===h.ad?' selected':'')+'>'+escapeHtml(h.ad)+'</option>'; }).join('');
  var granulOptions = '<option value="">— seçilmedi —</option>'+
    granulCinsleri.map(function(p){ return '<option value="'+escapeHtml(p.ad)+'"'+(isEdit&&editEntry.girdiTuru==='granul'&&editEntry.hammaddeCinsi===p.ad?' selected':'')+'>'+escapeHtml(p.ad)+'</option>'; }).join('');
  var girdiTuruBaslangic = (isEdit && editEntry.girdiTuru==='granul') ? 'granul' : 'hammadde';
  return '<div class="section-title" style="margin-top:0;">Bidon Üretimi</div>'+
    '<div class="card" style="max-width:560px;">'+
      (isEdit ? '<h3 style="margin-bottom:16px; text-transform:none; font-size:16px; color:var(--text);">Kaydı Düzenle</h3>' : '')+
      '<div class="row">'+
        '<div class="field"><label>Tarih</label><input type="date" id="bu_tarih" value="'+(isEdit?editEntry.tarih:todayStr())+'"></div>'+
        '<div class="field"><label>Vardiya</label><select id="bu_vardiya"><option value="gunduz">Gündüz</option><option value="gece">Gece</option></select></div>'+
      '</div>'+
      '<div class="field"><label>Bidon Tipi</label><select id="bu_urun">'+options+'</select></div>'+
      '<div class="row">'+
        '<div class="field"><label>Üretilen Adet</label><input type="number" id="bu_adet" min="0" step="1" value="'+(isEdit?editEntry.kg:'')+'" placeholder="örn. 5000"></div>'+
        '<div class="field"><label>Fire Adedi (adet)</label><input type="number" id="bu_fire" min="0" step="1" value="'+(isEdit?(editEntry.fireAdedi||0):0)+'" placeholder="örn. 50"></div>'+
      '</div>'+
      (hammaddeler.length===0 && granulCinsleri.length===0 ?
        '<div class="callout warn" style="margin-bottom:13px;">Henüz tanımlı hammadde/Granül cinsi yok — bu kayıt hangi girdinin tükendiğini kaydedemeyecek. <a id="bu_go_param_hm" style="color:var(--amber); cursor:pointer;">Parametreler</a>\'den ekleyebilirsiniz (opsiyonel).</div>'
        :
        '<div class="field"><label>Girdi Kaynağı</label><select id="bu_girdituru">'+
          '<option value="hammadde"'+(girdiTuruBaslangic==='hammadde'?' selected':'')+'>Hammadde (bu birimin kendi satın aldığı)</option>'+
          '<option value="granul"'+(girdiTuruBaslangic==='granul'?' selected':'')+'>Granül (Genel Fabrika\'nın paylaşımlı Granül stoğu)</option>'+
        '</select></div>'+
        '<div class="field" id="bu_hammadde_alani" style="display:'+(girdiTuruBaslangic==='hammadde'?'block':'none')+';"><label>Kullanılan Hammadde Cinsi</label><select id="bu_hammadde">'+hammaddeOptions+'</select></div>'+
        '<div class="field" id="bu_granul_alani" style="display:'+(girdiTuruBaslangic==='granul'?'block':'none')+';"><label>Kullanılan Granül Cinsi</label><select id="bu_granul">'+granulOptions+'</select></div>')+
      '<div class="field"><label>Kullanılan Miktar (kg) — otomatik hesaplanır</label><input type="number" id="bu_kg" step="0.01" disabled style="opacity:.75;"></div>'+
      '<div class="note" style="margin:-6px 0 13px;">Kullanılan miktar = (Üretilen Adet + Fire Adedi) × Ürün Gramajı — bidon tipinin Parametreler sekmesinde tanımlı gramajına göre otomatik hesaplanır, elle değiştirilemez. Girdi seçilirse, bu miktar seçilen kaynağın (hammadde ya da Genel Fabrika Granül) stoğundan düşer.</div>'+
      '<div class="field"><label>Not (opsiyonel)</label><textarea id="bu_not" rows="2">'+(isEdit?escapeHtml(editEntry.notlar||''):'')+'</textarea></div>'+
      '<button class="btn" id="bu_save">'+(isEdit?'Kaydı Güncelle':'Kaydı Kaydet')+'</button>'+
      (isEdit ? ' <button class="btn ghost" id="bu_cancel">Vazgeç</button>' : '')+
    '</div>';
}

function initBidonUretimForm(editEntry){
  var isEdit = !!editEntry;
  var goParamLink = document.getElementById('bu_go_param');
  if(goParamLink){ goParamLink.addEventListener('click', genelFabrikaParametrelerineGit); return; }

  var urunSel = document.getElementById('bu_urun');
  var adetInput = document.getElementById('bu_adet');
  var fireInput = document.getElementById('bu_fire');
  var kgInput = document.getElementById('bu_kg');
  var vardiyaSel = document.getElementById('bu_vardiya');
  var hammaddeSel = document.getElementById('bu_hammadde');
  var granulSel = document.getElementById('bu_granul');
  var girdiTuruSel = document.getElementById('bu_girdituru');
  var hammaddeAlani = document.getElementById('bu_hammadde_alani');
  var granulAlani = document.getElementById('bu_granul_alani');
  if(!urunSel || !adetInput) return; // ürün listesi boşsa form hiç basılmamış olabilir

  var goParamHmLink = document.getElementById('bu_go_param_hm');
  if(goParamHmLink) goParamHmLink.addEventListener('click', genelFabrikaParametrelerineGit);

  if(isEdit && editEntry.urun) urunSel.value = editEntry.urun;
  if(isEdit && editEntry.vardiya) vardiyaSel.value = editEntry.vardiya;

  if(girdiTuruSel){
    girdiTuruSel.addEventListener('change', function(){
      var granulMi = girdiTuruSel.value === 'granul';
      if(hammaddeAlani) hammaddeAlani.style.display = granulMi ? 'none' : 'block';
      if(granulAlani) granulAlani.style.display = granulMi ? 'block' : 'none';
    });
  }

  function gramajBul(){
    var opt = urunSel.options[urunSel.selectedIndex];
    return opt ? (Number(opt.dataset.gramaj)||0) : 0;
  }
  function hesapla(){
    var adet = Number(adetInput.value)||0;
    var fire = Number(fireInput.value)||0;
    var gramajGram = gramajBul(); // ürün başına gram
    var kullanilanKg = (adet+fire) * gramajGram / 1000;
    kgInput.value = (adet||fire) ? kullanilanKg.toFixed(2) : '';
  }
  urunSel.addEventListener('change', hesapla);
  adetInput.addEventListener('input', hesapla);
  fireInput.addEventListener('input', hesapla);
  hesapla();

  var cancelBtn = document.getElementById('bu_cancel');
  if(cancelBtn) cancelBtn.addEventListener('click', function(){ activeTab='kayitlar'; renderTabs(); renderTabContent(); });

  document.getElementById('bu_save').addEventListener('click', function(){
    var btn = this;
    var tarih = document.getElementById('bu_tarih').value;
    var vardiya = vardiyaSel.value;
    var urun = urunSel.value;
    var adet = Number(adetInput.value)||0;
    var fire = Number(fireInput.value)||0;
    var kullanilan = Number(kgInput.value)||0;
    var notlar = document.getElementById('bu_not').value.trim();
    var girdiTuru = girdiTuruSel ? girdiTuruSel.value : 'hammadde';
    var girdiAdi = girdiTuru==='granul' ? (granulSel?granulSel.value:'') : (hammaddeSel?hammaddeSel.value:'');
    if(!tarih || !urun || !adet){ alert('Lütfen tarih, bidon tipi ve üretilen adet alanlarını doldurun.'); return; }
    var payload = {tarih:tarih, urun:urun, vardiya:vardiya, kg:adet, fireAdedi:fire, kullanilanCapak:kullanilan, capakCinsi:'', hammaddeCinsi:girdiAdi, girdiTuru:girdiTuru, notlar:notlar};
    var aciklama = (isEdit?'Bidon üretim kaydı güncelleme: ':'Yeni bidon üretim kaydı: ')+urun+', '+fmt(adet)+' adet ('+tarihGoster(tarih)+')';
    var fonksiyonAdi = isEdit ? 'updateEntry' : 'addEntry';
    var argListesi = isEdit ? [STATE.aktifBirimId, editEntry.id, payload] : [STATE.aktifBirimId, payload];
    btn.disabled = true; btn.textContent = isEdit?'Güncelleniyor…':'Kaydediliyor…';
    mutasyonCagirUretim(fonksiyonAdi, argListesi, aciklama, aktifBirimAdi(), !isEdit, function(entries, kuyruga){
      if(kuyruga){ btn.disabled=false; btn.textContent = isEdit?'Kaydı Güncelle':'Kaydı Kaydet'; return; }
      STATE.birimVeri.entries = entries;
      if(isEdit){
        activeTab = 'kayitlar';
        renderTabs(); renderTabContent();
      } else {
        showToast('Kayıt eklendi.');
        renderTabContent();
      }
    }, function(err){ alert(err.message); btn.disabled=false; btn.textContent = isEdit?'Kaydı Güncelle':'Kaydı Kaydet'; });
  });
}

function renderYeni(c, editEntry){
  // Boş ürün listesi kontrolü: Çapak Üretim Birimi kendi kontrolünü zaten ayrı yapıyor
  // (renderCapakUretimFormHTML), "diğer birim" (Şişirme gibi) kendi izole ürün listesine
  // (çekirdek Ürün Cinsleri + ek kategoriler BİRLEŞİK) bakar — Granül'ün merkezi listesiyle hiç ilgisi yoktur.
  var uygunUrunListesiBos = digerBirimMi()
    ? tumUrunlerBirlesik(STATE.birimVeri).length===0
    : (STATE.aktifBirimId !== 'capak-uretim-birimi' && STATE.merkeziCinsler.urunler.length===0);
  if(uygunUrunListesiBos){
    c.innerHTML = '<div class="callout warn">Henüz tanımlı ürün yok. Kayıt ekleyebilmek için önce <a id="go_ayarlar" style="color:var(--amber); cursor:pointer;">Parametreler</a> sayfasından en az bir ürün cinsi ekleyin.</div>';
    (document.getElementById('go_ayarlar')||{addEventListener:function(){}}).addEventListener('click', genelFabrikaParametrelerineGit);
    return;
  }
  c.innerHTML = '<div id="yeni_kayit_icerik"></div>';
  renderUretimKaydiIcerik(document.getElementById('yeni_kayit_icerik'), editEntry);
}

// ---------- Yeni Kayıt > Üretim Kaydı: Granül Üretim Kaydı + Çapak Üretim Kaydı (yan yana) ----------
function renderUretimKaydiIcerik(c, editEntry){
  var isEdit = !!editEntry;
  var basliklar = STATE.merkeziCinsler.cinsBasliklari;

  // Çapak Üretim Birimi'nde sadece Hurdadan Çapak Üretimi formu gösterilir (yeni kayıt VEYA
  // düzenleme, ikisinde de) — Granül üretim formu bu birimde hiç görünmez (birime özel, sabit
  // bir kural; ayarlanabilir değildir).
  if(STATE.aktifBirimId === 'capak-uretim-birimi'){
    c.innerHTML =
      (isEdit ? '' : '<div class="section-title" style="margin-top:0;">'+escapeHtml(cinsAdiKisa(basliklar.hurda))+'dan '+escapeHtml(cinsAdiKisa(basliklar.capak))+' Üretimi</div>')+
      renderCapakUretimFormHTML(editEntry);
    initCapakUretimForm(editEntry);
    return;
  }

  // "Diğer birim" (örn. Şişirme Birimi): adet bazlı Bidon Üretimi formu — Granül'ün elektrik/
  // işçilik/Agromel/Çapak mantığıyla hiç ilgisi yok, tamamen ayrı ve daha basit bir model.
  if(digerBirimMi()){
    c.innerHTML = renderBidonUretimFormHTML(editEntry);
    initBidonUretimForm(editEntry);
    return;
  }

  var productOptions = STATE.merkeziCinsler.urunler.map(function(p){ return '<option value="'+escapeHtml(p.ad)+'">'+escapeHtml(p.ad)+'</option>'; }).join('');
  var vardiyaSuresiGosterim = isEdit ? editEntry.vardiyaSuresi : STATE.birimVeri.settings.vardiyaSuresi;
  var aktif = STATE.merkeziCinsler.cinsAktif;
  var capakAlanlariGoster = aktif.capak;

  if(!isEdit && !aktif.granul){
    c.innerHTML = '<div class="callout warn">Bu birimde "'+escapeHtml(basliklar.granul)+'" kategorisi kapalı olduğu için üretim kaydı girilemiyor. <a id="uk_go_param" style="color:var(--amber); cursor:pointer;">Parametreler</a> sayfasından açabilirsiniz.</div>';
    var goParamLink2 = document.getElementById('uk_go_param');
    if(goParamLink2) goParamLink2.addEventListener('click', genelFabrikaParametrelerineGit);
    return;
  }

  // Düzenlemede: kayıtta fireOrani zaten varsa onu kullan; yoksa (bu özellikten önce girilmiş eski
  // bir kayıtsa) mevcut kullanılan/üretilen oranından geriye dönük türet — açıldığında otomatik
  // hesaplama, kaydın o anki gerçek verisini SESSİZCE değiştirmesin diye.
  var fireOraniBaslangic = 0;
  if(isEdit && capakAlanlariGoster){
    if(editEntry.fireOrani !== undefined && editEntry.fireOrani !== null){
      fireOraniBaslangic = editEntry.fireOrani;
    } else if(Number(editEntry.kg) > 0 && Number(editEntry.kullanilanCapak) > 0){
      fireOraniBaslangic = Math.round(((Number(editEntry.kullanilanCapak) / Number(editEntry.kg)) - 1) * 100 * 100) / 100;
    }
  }

  var granulFormHTML =
    (isEdit ? '' : '<div class="section-title" style="margin-top:0;">'+(capakAlanlariGoster?escapeHtml(cinsAdiKisa(basliklar.capak))+'tan '+escapeHtml(cinsAdiKisa(basliklar.granul)):escapeHtml(cinsAdiKisa(basliklar.granul)))+' Üretimi</div>')+
    '<div class="card" style="max-width:560px;">'+
      (isEdit ? '<h3 style="margin-bottom:16px; text-transform:none; font-size:16px; color:var(--text);">Kaydı Düzenle</h3>' : '')+
      '<div class="row">'+
        '<div class="field"><label>Tarih</label><input type="date" id="f_tarih" value="'+(isEdit?editEntry.tarih:todayStr())+'"></div>'+
        '<div class="field"><label>'+escapeHtml(basliklar.granul)+'</label><select id="f_urun">'+productOptions+'</select></div>'+
      '</div>'+
      '<div class="row">'+
        '<div class="field"><label>Vardiya</label><select id="f_vardiya">'+
          '<option value="gunduz">Gündüz Vardiyası</option><option value="gece">Gece Vardiyası</option>'+
        '</select></div>'+
        '<div class="field"><label>Agromel Yapıldı mı?</label><select id="f_agromel">'+
          '<option value="evet">Evet</option><option value="hayir">Hayır</option>'+
        '</select></div>'+
      '</div>'+
      (capakAlanlariGoster ?
        '<div class="row">'+
          '<div class="field"><label>Kullanılan '+escapeHtml(basliklar.capak)+'</label><select id="f_capakcinsi">'+
            '<option value="">— seçiniz —</option>'+
            STATE.merkeziCinsler.capakCinsleri.map(function(p){ return '<option value="'+escapeHtml(p.ad)+'">'+escapeHtml(p.ad)+'</option>'; }).join('')+
          '</select></div>'+
          '<div class="field"><label>Fire Oranı (%)</label><input type="number" id="f_fire" min="0" max="100" step="0.01" value="'+fireOraniBaslangic+'" placeholder="örn. 4"></div>'+
        '</div>'+
        '<div class="field"><label>Çapak Kaynağı</label><select id="f_capakkaynagi">'+
          '<option value="normal"'+(isEdit&&editEntry.capakKaynagi==='iscilik'?'':' selected')+'>Normal (parayla alınan çapak)</option>'+
          '<option value="iscilik"'+(isEdit&&editEntry.capakKaynagi==='iscilik'?' selected':'')+'>İşçilik (müşterinin kendi getirdiği, bedelsiz çapak)</option>'+
        '</select></div>'+
        '<div class="note" style="margin:-6px 0 13px;" id="f_capakkaynagi_not"></div>'
        : '')+
      '<div class="field"><label>Üretilen Kg ('+escapeHtml(basliklar.granul)+')</label><input type="number" id="f_kg" min="0" step="0.01" value="'+(isEdit?editEntry.kg:'')+'" placeholder="örn. 12000"></div>'+
      (capakAlanlariGoster ?
        '<div class="field"><label>Kullanılan Miktar (kg) — otomatik hesaplanır</label><input type="number" id="f_capak" step="0.01" disabled style="opacity:.75;"></div>'
        : '')+
      '<div class="note" style="margin:-6px 0 13px;">Vardiya süresi sabit <b class="mono">'+fmt(vardiyaSuresiGosterim)+' saat</b> kabul edilir (Parametreler\'den değiştirilebilir). Saatlik verim, girdiğiniz kg\'ye göre otomatik hesaplanır.'+(capakAlanlariGoster?' Kullanılan miktar, "Üretilen Kg" ve "Fire Oranı"na göre otomatik hesaplanır ve elle değiştirilemez; Stok sekmesindeki ilgili '+escapeHtml(basliklar.capak)+' stoğundan otomatik düşer.':'')+'</div>'+
      '<div class="field"><label>Not (opsiyonel)</label><textarea id="f_not" rows="2" placeholder="arıza, duruş, vb.">'+(isEdit?escapeHtml(editEntry.notlar||''):'')+'</textarea></div>'+
      '<div class="preview" id="f_preview"></div>'+
      '<div class="modal-actions">'+(isEdit?'<button class="btn ghost" id="f_cancel">Vazgeç</button>':'')+
        '<button class="btn" id="f_save">'+(isEdit?'Güncelle':'Kaydı Kaydet')+'</button>'+
      '</div>'+
    '</div>';

  c.innerHTML = granulFormHTML;

  var urunSel = document.getElementById('f_urun');
  if(isEdit) urunSel.value = editEntry.urun;
  var vardiyaSel = document.getElementById('f_vardiya');
  if(isEdit && editEntry.vardiya) vardiyaSel.value = editEntry.vardiya;
  var agromelSel = document.getElementById('f_agromel');
  if(isEdit) agromelSel.value = (editEntry.agromelYapildi===false) ? 'hayir' : 'evet';
  var kgInput = document.getElementById('f_kg');
  var capakInput = document.getElementById('f_capak'); // capakAlanlariGoster false ise null olur, artık disabled/otomatik
  var fireInput = document.getElementById('f_fire'); // capakAlanlariGoster false ise null olur
  var capakCinsiSel = document.getElementById('f_capakcinsi'); // capakAlanlariGoster false ise null olur
  var capakKaynagiSel = document.getElementById('f_capakkaynagi'); // capakAlanlariGoster false ise null olur
  if(capakKaynagiSel){
    var kaynakNotGuncelle = function(){
      var notEl = document.getElementById('f_capakkaynagi_not');
      if(!notEl) return;
      if(capakKaynagiSel.value === 'iscilik'){
        notEl.innerHTML = 'Bu üretim <b>İşçilik Çapak</b> stoğundan düşecek ve çıktısı normal Granül stoğundan AYRI bir "İşçilik Granül" stoğuna eklenecek.';
      } else {
        notEl.innerHTML = 'Bu üretim normal (parayla alınan) '+escapeHtml(basliklar.capak)+' stoğundan düşecek.';
      }
    };
    capakKaynagiSel.addEventListener('change', kaynakNotGuncelle);
    kaynakNotGuncelle();
  }
  // Kullanılan Çapak miktarı artık elle girilmiyor: Üretilen Kg ve Fire Oranı'na göre otomatik
  // hesaplanır. Formül: kullanılan = üretilen × (1 + fire/100) — örn. 900 kg üretim, %4 fire ise
  // kullanılan = 936 kg (üretimden fazlası, fire kaybı yüzünden — girdi her zaman çıktıdan fazladır).
  function capakOtomatikHesapla(){
    if(!capakInput) return;
    var kg = Number(kgInput.value) || 0;
    var fire = fireInput ? (Number(fireInput.value) || 0) : 0;
    capakInput.value = kg ? (kg * (1 + fire/100)).toFixed(2) : '';
  }
  if(fireInput) fireInput.addEventListener('input', capakOtomatikHesapla);
  capakOtomatikHesapla();
  if(isEdit && editEntry.capakCinsi && capakCinsiSel){
    capakCinsiSel.value = editEntry.capakCinsi;
  } else if(!isEdit && capakCinsiSel && urunSel.value){
    // Yeni kayıtta, seçili Granül ürünle aynı ön ada sahip Çapak cinsi varsa otomatik seçilir
    // (örn. "Şeffaf Naylon Granül" seçilince "Şeffaf Naylon Çapak" otomatik gelir).
    var otomatikCapak = esOnAdliCinsBul(urunSel.value, STATE.merkeziCinsler.capakCinsleri);
    if(otomatikCapak) capakCinsiSel.value = otomatikCapak;
  }
  urunSel.addEventListener('change', function(){
    if(capakCinsiSel){
      var eslesen = esOnAdliCinsBul(urunSel.value, STATE.merkeziCinsler.capakCinsleri);
      if(eslesen) capakCinsiSel.value = eslesen;
    }
  });
  var tarihInput = document.getElementById('f_tarih');

  function buildPreviewEntry(kg, vardiya, agromelYapildi, tarih){
    if(isEdit && editEntry.elektrikFiyati !== undefined){
      // eski (legacy) kayıt: kendi gömülü maliyet parametreleriyle önizleme
      return {
        kg:kg, vardiya:vardiya, agromelYapildi:agromelYapildi, tarih:tarih,
        vardiyaSuresi: editEntry.vardiyaSuresi,
        elektrikFiyati: editEntry.elektrikFiyati, aylikCalismaSuresi: editEntry.aylikCalismaSuresi,
        agromelKapasite: editEntry.agromelKapasite, granulKapasite: editEntry.granulKapasite,
        agromelGunduzMaas: editEntry.agromelGunduzMaas, agromelGeceMaas: editEntry.agromelGeceMaas,
        granulGunduzMaas: editEntry.granulGunduzMaas, granulGeceMaas: editEntry.granulGeceMaas
      };
    }
    var vardiyaSuresi = isEdit ? editEntry.vardiyaSuresi : STATE.birimVeri.settings.vardiyaSuresi;
    return {kg:kg, vardiya:vardiya, agromelYapildi:agromelYapildi, tarih:tarih, vardiyaSuresi:vardiyaSuresi};
  }

  function updatePreview(){
    capakOtomatikHesapla(); // Kullanılan Çapak miktarını (varsa) güncel kg/fire'a göre tazele
    var kg = Number(kgInput.value);
    var vardiya = vardiyaSel.value, agromelYapildi = agromelSel.value === 'evet';
    var tarih = tarihInput.value;
    var box = document.getElementById('f_preview'); if(!box) return;
    if(!kg){ box.innerHTML = '<div class="note">Kg girildiğinde süre/verim önizlemesi burada görünecek.</div>'; return; }
    // Aynı tarih+vardiyada zaten kayıtlı başka ürün(ler) varsa (düzenlenen kaydın eskisi hariç),
    // önizleme de o toplam grup tonajını dikkate alır — kaydedince göreceği rakamla aynı olsun diye.
    var mevcutGrupKg = vardiyaGrupToplamKg({tarih:tarih, vardiya:vardiya}, STATE.birimVeri, 'entries', 'kg');
    if(isEdit && editEntry.tarih === tarih && editEntry.vardiya === vardiya){
      mevcutGrupKg -= Number(editEntry.kg)||0;
    }
    var c2 = computeCosts(buildPreviewEntry(kg, vardiya, agromelYapildi, tarih), null, mevcutGrupKg + kg);
    var html =
      '<div class="line"><span>Bu Kaydın Süresi (otomatik)</span><b>'+fmt(c2.gosterilenSure)+' saat</b></div>'+
      '<div class="line"><span>Saatlik Verim (otomatik, vardiya toplamına göre)</span><b style="color:var(--amber);">'+fmt(c2.saatlikVerim)+' kg/saat</b></div>';
    if(c2.maliyetGirildi){
      html +=
        '<div class="line"><span>Agromel Elektrik Maliyeti'+(agromelYapildi?'':' (yapılmadı)')+'</span><b>'+fmt(c2.agromelElektrik)+' TL</b></div>'+
        '<div class="line"><span>Granül Elektrik Maliyeti</span><b>'+fmt(c2.granulElektrik)+' TL</b></div>'+
        '<div class="line"><span>Agromel İşçilik Maliyeti ('+(vardiya==='gece'?'Gece':'Gündüz')+')'+(agromelYapildi?'':' (yapılmadı)')+'</span><b>'+fmt(c2.iscilikAgromel)+' TL</b></div>'+
        '<div class="line"><span>Granül İşçilik Maliyeti ('+(vardiya==='gece'?'Gece':'Gündüz')+')</span><b>'+fmt(c2.iscilikGranul)+' TL</b></div>'+
        '<div class="line total"><span>Toplam maliyet / Birim maliyet</span><b>'+fmt(c2.toplamMaliyet)+' TL — '+fmt(c2.birimMaliyet)+' TL/kg</b></div>';
    } else {
      html += '<div class="note" style="margin-top:8px;">Bu ayın (<b class="mono">'+escapeHtml((tarih||'').slice(0,7))+'</b>) maliyet parametreleri henüz girilmedi. Ay sonunda <b>Aylık Rapor</b> sekmesinden o ayın elektrik fiyatını ve maaşlarını toplu girdiğinizde bu kaydın maliyeti de otomatik hesaplanacak.</div>';
    }
    var capak = capakInput ? Number(capakInput.value) : 0;
    if(capak){
      var fire = capak - kg;
      var firePct = capak ? (fire/capak*100) : 0;
      html += '<div class="line" style="margin-top:8px; border-top:1px solid var(--line); padding-top:8px;"><span>Fire</span><b style="color:'+(fire<0?'var(--danger)':'var(--amber)')+';">'+fmt(fire)+' kg ('+fmt(firePct)+'%)</b></div>';
    }
    box.innerHTML = html;
  }
  kgInput.addEventListener('input', updatePreview);
  vardiyaSel.addEventListener('change', updatePreview);
  agromelSel.addEventListener('change', updatePreview);
  tarihInput.addEventListener('change', updatePreview);
  updatePreview();

  (document.getElementById('f_save')||{addEventListener:function(){}}).addEventListener('click', function(){
    var btn = this;
    var tarih = (document.getElementById('f_tarih')||{value:''}).value;
    var urun = urunSel.value, vardiya = vardiyaSel.value, agromelYapildi = agromelSel.value==='evet';
    var kg = Number(kgInput.value);
    var capakCinsi = capakCinsiSel ? capakCinsiSel.value : '';
    var fire = fireInput ? (Number(fireInput.value) || 0) : 0;
    var kullanilanCapak = capakInput ? (Number(capakInput.value) || 0) : 0;
    var capakKaynagi = capakKaynagiSel ? capakKaynagiSel.value : 'normal';
    var notlar = (document.getElementById('f_not')||{value:''}).value.trim();
    if(!tarih || !urun || !kg){ alert('Lütfen tarih, ürün ve kg alanlarını doldurun.'); return; }
    if(kullanilanCapak && !capakCinsi){ alert('Kullanılan miktar hesaplandıysa, lütfen Çapak cinsini de seçin.'); return; }
    btn.disabled = true; btn.textContent = 'Kaydediliyor…';
    var payload = {tarih:tarih, urun:urun, vardiya:vardiya, agromelYapildi:agromelYapildi, kg:kg, capakCinsi:capakCinsi, kullanilanCapak:kullanilanCapak, capakKaynagi:capakKaynagi, fireOrani:fire, notlar:notlar};
    var aciklama = (isEdit?'Granül kaydı güncelleme: ':'Yeni Granül üretim kaydı: ')+urun+', '+fmtKg(kg)+' kg ('+tarihGoster(tarih)+')';
    var fonksiyonAdi = isEdit ? 'updateEntry' : 'addEntry';
    var argListesi = isEdit ? [STATE.aktifBirimId, editEntry.id, payload] : [STATE.aktifBirimId, payload];
    mutasyonCagirUretim(fonksiyonAdi, argListesi, aciklama, aktifBirimAdi(), !isEdit, function(entries, kuyruga){
      if(kuyruga){ btn.disabled = false; btn.textContent = isEdit?'Güncelle':'Kaydı Kaydet'; return; }
      STATE.birimVeri.entries = entries;
      if(isEdit){
        // Düzenleme genelde Kayıtlar'dan başlatıldığı için, güncelleme sonrası oraya dönmek doğaldır.
        activeTab = 'kayitlar';
        renderTabs(); renderTabContent();
      } else {
        // Yeni kayıt eklerken aynı sekmede kalınır — art arda birden çok kayıt girmek kolaylaşır.
        showToast('Kayıt eklendi.');
        renderTabContent();
      }
    }, function(err){ alert(err.message); btn.disabled=false; btn.textContent = isEdit?'Güncelle':'Kaydı Kaydet'; });
  });
  var cancelBtn = document.getElementById('f_cancel');
  if(cancelBtn) cancelBtn.addEventListener('click', function(){ activeTab='kayitlar'; renderTabs(); renderTabContent(); });

  if(!isEdit) initCapakUretimForm();
}

// ============================================================
// KAYITLAR
// ============================================================
function localISO(d){
  var y=d.getFullYear(), m=String(d.getMonth()+1).padStart(2,'0'), day=String(d.getDate()).padStart(2,'0');
  return y+'-'+m+'-'+day;
}

function renderKayitlar(c){
  c.innerHTML =
    '<div class="stage-switch" id="kayitlar_alt_sekme" style="margin-bottom:18px; max-width:520px;"></div>'+
    '<div id="kayitlar_icerik"></div>';
  renderKayitlarAltSekmeler();
  renderKayitlarIcerik();
}

function renderKayitlarAltSekmeler(){
  var box = document.getElementById('kayitlar_alt_sekme');
  // "Diğer birim" (örn. Şişirme Birimi) Granül/Çapak Üretim Birimi'nin MERKEZİ cins listesini
  // değil, kendi izole (STATE.birimVeri) cins başlıklarını/aktifliğini kullanır.
  var basliklar = digerBirimMi() ? STATE.birimVeri.cinsBasliklari : STATE.merkeziCinsler.cinsBasliklari;
  var aktif = digerBirimMi() ? STATE.birimVeri.cinsAktif : STATE.merkeziCinsler.cinsAktif;
  // Granül Birimi sadece kendi ürettiği Granül'ün kayıtlarıyla ilgilenir; Çapak Üretim Birimi
  // hem tükettiği Hurda'nın hem de ürettiği Çapak'ın kayıtlarıyla ilgilenir.
  var izinliKategoriler = BIRIM_ILGILI_KATEGORILER[STATE.aktifBirimId] || ['hurda','capak','granul'];
  var sekmeler = [];
  if(aktif.hurda && izinliKategoriler.indexOf('hurda') !== -1) sekmeler.push({id:'hurda', label:basliklar.hurda+' Kayıtları'});
  if(aktif.capak && izinliKategoriler.indexOf('capak') !== -1) sekmeler.push({id:'capak', label:basliklar.capak+' Kayıtları'});
  if(aktif.granul && izinliKategoriler.indexOf('granul') !== -1) sekmeler.push({id:'granul', label:basliklar.granul+' Kayıtları'});
  if(sekmeler.length > 0 && !sekmeler.some(function(s){ return s.id === kayitlarAltSekme; })){
    kayitlarAltSekme = sekmeler[0].id;
  }
  box.innerHTML = sekmeler.map(function(s){
    return '<button class="stage-btn '+(kayitlarAltSekme===s.id?'active':'')+'" data-kayit-sekme="'+s.id+'">'+escapeHtml(s.label)+'</button>';
  }).join('') || '<div class="note">Bu birimde aktif bir kategori yok.</div>';
  Array.prototype.forEach.call(box.querySelectorAll('button'), function(b){
    b.addEventListener('click', function(){
      kayitlarAltSekme = b.dataset.kayitSekme;
      renderKayitlarAltSekmeler();
      renderKayitlarIcerik();
    });
  });
}

function renderKayitlarIcerik(){
  var c = document.getElementById('kayitlar_icerik'); if(!c) return;
  var aktif = digerBirimMi() ? STATE.birimVeri.cinsAktif : STATE.merkeziCinsler.cinsAktif;
  var izinliKategoriler = BIRIM_ILGILI_KATEGORILER[STATE.aktifBirimId] || ['hurda','capak','granul'];
  if(kayitlarAltSekme==='hurda' && aktif.hurda && izinliKategoriler.indexOf('hurda') !== -1) return renderHurdaKayitlari(c);
  if(kayitlarAltSekme==='capak' && aktif.capak && izinliKategoriler.indexOf('capak') !== -1) return renderCapakKayitlari(c);
  if(kayitlarAltSekme==='granul' && aktif.granul && izinliKategoriler.indexOf('granul') !== -1){
    return digerBirimMi() ? renderBidonKayitlari(c) : renderGranulKayitlari(c);
  }
  c.innerHTML = '<div class="callout warn">Bu birimde şu an aktif bir kategori yok. <a id="ky_go_param" style="color:var(--amber); cursor:pointer;">Parametreler</a> sayfasından bir kategori açabilirsiniz.</div>';
  var lnk = document.getElementById('ky_go_param');
  if(lnk) lnk.addEventListener('click', genelFabrikaParametrelerineGit);
}

// ---------- Kayıtlar > Hurda Kayıtları ----------
function renderHurdaKayitlari(c){
  var basliklar = STATE.merkeziCinsler.cinsBasliklari;
  c.innerHTML =
    '<div class="section-title" style="margin-top:0;">Satın Alınan '+escapeHtml(basliklar.hurda)+'</div>'+
    '<div id="hk_liste"></div>';

  var cinsSecenekleri = STATE.merkeziCinsler.hurdaCinsleri.map(function(p){ return p.ad; });
  function ekranSatir(h){
    var fkg = fireliKg(h);
    var maliyet = girisMaliyetiKgBasi(h);
    return '<tr><td class="txt">'+escapeHtml(tarihGoster(h.tarih))+'</td><td class="txt"><span class="tag '+tagClassFor(h.urun)+'">'+escapeHtml(h.urun)+'</span></td>'+
      '<td>'+fmtKg(h.kg)+'</td>'+
      '<td>'+(Number(h.fireOrani) ? fmt(h.fireOrani)+'%' : '—')+'</td>'+
      '<td>'+fmtKg(fkg)+'</td>'+
      '<td>'+(h.fiyat?fmt(h.fiyat)+' TL/kg':'—')+'</td>'+
      '<td>'+(Number(h.nakliyeUcreti) ? fmt(h.nakliyeUcreti)+' TL' : '—')+'</td>'+
      '<td>'+(h.fiyat?fmt(girisNakliyeliToplamMaliyet(h))+' TL':'—')+'</td>'+
      '<td>'+(h.fiyat?fmt(maliyet)+' TL/kg':'—')+'</td>'+
      '<td class="txt" style="max-width:220px; white-space:pre-wrap;">'+(escapeHtml(h.notlar)||'<span style="color:var(--muted);">—</span>')+'</td>'+
      '<td class="txt">'+escapeHtml(h.girenAd||'')+'</td>'+
      '<td style="white-space:nowrap;">'+(canMutate()?('<button class="btn ghost small" data-hk-edit="'+h.id+'">Düzenle</button> <button class="btn danger small" data-hk-del="'+h.id+'">Sil</button>'):'')+'</td></tr>';
  }
  function pdfSatir(h){
    return '<tr><td>'+escapeHtml(pdfTarihFormat(h.tarih))+'</td><td>'+escapeHtml(h.urun)+'</td><td>'+fmtKg(h.kg)+'</td>'+
      '<td>'+(Number(h.fireOrani)?fmt(h.fireOrani)+'%':'—')+'</td>'+
      '<td>'+(h.fiyat?fmt(h.fiyat):'—')+'</td>'+
      '<td>'+(Number(h.nakliyeUcreti)?fmt(h.nakliyeUcreti):'—')+'</td>'+
      '<td>'+(h.fiyat?fmt(girisNakliyeliToplamMaliyet(h)):'—')+'</td>'+
      '<td>'+(h.fiyat?fmt(girisMaliyetiKgBasi(h)):'—')+'</td>'+
      '<td>'+escapeHtml(h.notlar||'')+'</td><td>'+escapeHtml(h.girenAd||'')+'</td></tr>';
  }
  renderBasitFiltreliListe('hk_liste', function(){ return STATE.merkeziSatinAlmalar.hurdaGirisleri; }, 'urun', 'kg', cinsSecenekleri,
    'Satın Alınan '+basliklar.hurda+' Raporu',
    ['Tarih', basliklar.hurda, 'Kg', 'Fire %', 'Fiyat (TL/kg)', 'Nakliye (TL)', 'Toplam Maliyet', 'Maliyet (TL/kg)', 'Not', 'Giren', ''], ekranSatir,
    ['Tarih', basliklar.hurda, 'Kg', 'Fire %', 'Fiyat (TL/kg)', 'Nakliye (TL)', 'Toplam Maliyet', 'Maliyet (TL/kg)', 'Not', 'Giren'], pdfSatir,
    function(tabloBox){
      Array.prototype.forEach.call(tabloBox.querySelectorAll('[data-hk-edit]'), function(b){
        b.addEventListener('click', function(){
          var oge = STATE.merkeziSatinAlmalar.hurdaGirisleri.find(function(x){ return x.id === b.dataset.hkEdit; });
          if(!oge) return;
          activeStage = 'satinalma'; activeTab = 'panel';
          renderApp();
          renderSatinAlmaEkrani(document.getElementById('content'), Object.assign({_tur:'hurda'}, oge));
        });
      });
      Array.prototype.forEach.call(tabloBox.querySelectorAll('[data-hk-del]'), function(b){
        b.addEventListener('click', function(){
          var oge = STATE.merkeziSatinAlmalar.hurdaGirisleri.find(function(x){ return x.id === b.dataset.hkDel; });
          showConfirm('Bu kaydı silmek istediğinize emin misiniz?', 'Sil', function(){
            var aciklama = basliklar.hurda+' satın alma silme: '+(oge?oge.urun+', '+fmtKg(oge.kg)+' kg':'');
            mutasyonCagirUretim('deleteHurdaGirisi', ['merkezi', b.dataset.hkDel], aciklama, 'Satın Alma', false, function(liste, kuyruga){
              if(kuyruga) return;
              STATE.merkeziSatinAlmalar.hurdaGirisleri = liste;
              renderHurdaKayitlari(c);
            });
          });
        });
      });
    });
}

