// ============================================================
// PARAMETRELER — Değişken Parametreler (temel 4 + yöneticinin serbestçe yönettiği
// Ek Parametreler) ve Ürün Cinsleri (Hurda/Çapak/Granül), bir birime ait.
// ============================================================
// ============================================================
// GERİ DÖNÜŞÜM KUTUSU (yalnızca yöneticiler görebilir) — bir birime ait silinen kayıtlar,
// türlerine göre gruplanmış şekilde burada listelenir. Yönetici istediği zaman geri getirebilir.
// ============================================================
function copOzetMetni(cop){
  var v = cop.veri;
  switch(cop.tur){
    case 'entry': return (v.tarih||'')+' — '+(v.urun||'')+' — '+fmtKg(v.kg)+' kg';
    case 'capakUretimi': return (v.tarih||'')+' — '+(v.hurdaCinsi||v.urun||'')+' → '+(v.capakCinsi||v.urun||'')+' — '+fmtKg(v.uretilenCapak)+' kg';
    case 'hurdaGirisi': case 'capakGirisi': case 'granulGirisi': return (v.tarih||'')+' — '+(v.urun||'')+' — '+fmtKg(v.kg)+' kg';
    case 'personel': return (v.ad||'')+' — '+(v.unvan||'')+' — '+fmt(v.maas)+' TL';
    case 'unvan': return String(v);
    case 'hurdaCinsi': case 'capakCinsi': case 'urun': return v.ad||'';
    case 'ekParametre': return (v.ad||'')+': '+(v.deger||'');
    case 'aylikKapanis': return v.ay||'';
    default: return '(kayıt)';
  }
}

function renderCopKutusu(c){
  c.innerHTML = '<div class="note">Yükleniyor…</div>';
  window.api.getBirimData(STATE.aktifBirimId).then(function(veri){
    birimVerisiniStateAAyir(veri);
    renderCopKutusuIcerik(c);
  }).catch(function(err){ c.innerHTML = '<div class="callout warn">'+escapeHtml(err.message)+'</div>'; });
}

function renderCopKutusuIcerik(c){
  var liste = STATE.birimVeri.copKutusu || [];
  if(liste.length===0){
    c.innerHTML = '<div class="callout">Geri dönüşüm kutusu boş. Silinen kayıtlar burada, türlerine göre gruplanmış olarak görünecek ve istediğiniz zaman geri getirebileceksiniz.</div>';
    return;
  }
  var gruplar = {};
  liste.forEach(function(cop){
    if(!gruplar[cop.tur]) gruplar[cop.tur] = [];
    gruplar[cop.tur].push(cop);
  });
  var turSirasi = ['entry','capakUretimi','hurdaGirisi','capakGirisi','granulGirisi','personel','unvan','hurdaCinsi','capakCinsi','urun','ekParametre','aylikKapanis'];
  var html = '<div class="toolbar" style="justify-content:space-between;">'+
      '<div class="callout" style="margin:0; flex:1;">Silinen kayıtlar burada, türüne göre gruplanmış olarak tutulur. "Geri Getir" ile geri getirebilir, "Kalıcı Sil" ile TAMAMEN (geri getirilemeyecek şekilde) silebilirsiniz.</div>'+
      '<div style="display:flex; gap:8px; margin-left:12px; flex:0 0 auto;">'+
        '<button class="btn ghost small" id="cop_yenile">Yenile</button>'+
        '<button class="btn danger small" id="cop_tumunu_bosalt">Tümünü Kalıcı Sil</button>'+
      '</div>'+
    '</div>';
  turSirasi.forEach(function(tur){
    var grup = gruplar[tur];
    if(!grup || grup.length===0) return;
    var etiket = grup[0].etiket || tur;
    html += '<div class="section-title">'+escapeHtml(etiket)+' ('+grup.length+')</div>'+
      '<div class="card"><table><thead><tr><th>Özet</th><th>Silinme Zamanı</th><th>Silen</th><th></th></tr></thead><tbody>'+
      grup.slice().sort(function(a,b){ return (b.silinmeZamani||'').localeCompare(a.silinmeZamani||''); }).map(function(cop){
        return '<tr><td class="txt">'+escapeHtml(copOzetMetni(cop))+'</td>'+
          '<td class="txt mono">'+escapeHtml(tarihGoster(cop.silinmeZamani))+'</td>'+
          '<td class="txt">'+escapeHtml(cop.silenKullanici||'')+'</td>'+
          '<td style="white-space:nowrap;"><button class="btn ghost small" data-cop-geri="'+cop.id+'">Geri Getir</button> <button class="btn danger small" data-cop-kalici-sil="'+cop.id+'">Kalıcı Sil</button></td></tr>';
      }).join('')+
    '</tbody></table></div>';
  });
  c.innerHTML = html;

  (document.getElementById('cop_yenile')||{addEventListener:function(){}}).addEventListener('click', function(){ renderCopKutusu(c); });

  (document.getElementById('cop_tumunu_bosalt')||{addEventListener:function(){}}).addEventListener('click', function(){
    showConfirm('Geri dönüşüm kutusundaki TÜM kayıtları (toplam '+liste.length+' adet) kalıcı olarak silmek istediğinize emin misiniz? Bu işlem GERİ ALINAMAZ.', 'Tümünü Kalıcı Sil', function(){
      window.api.emptyCopKutusu(STATE.aktifBirimId).then(function(copKutusu){
        STATE.birimVeri.copKutusu = copKutusu;
        showToast('Geri dönüşüm kutusu boşaltıldı.');
        renderCopKutusuIcerik(c);
      }).catch(function(err){ alert(err.message); });
    });
  });

  Array.prototype.forEach.call(c.querySelectorAll('[data-cop-geri]'), function(b){
    b.addEventListener('click', function(){
      var btn = b; btn.disabled = true; btn.textContent = 'Geri getiriliyor…';
      window.api.restoreCop(STATE.aktifBirimId, b.dataset.copGeri).then(function(bd){
        STATE.birimVeri = bd;
        showToast('Kayıt geri getirildi.');
        renderCopKutusuIcerik(c);
      }).catch(function(err){ alert(err.message); btn.disabled=false; btn.textContent='Geri Getir'; });
    });
  });

  Array.prototype.forEach.call(c.querySelectorAll('[data-cop-kalici-sil]'), function(b){
    b.addEventListener('click', function(){
      var copId = b.dataset.copKaliciSil;
      var oge = liste.find(function(x){ return x.id === copId; });
      showConfirm('"'+(oge?copOzetMetni(oge):'Bu kayıt')+'" kalıcı olarak silinsin mi? Bu işlem GERİ ALINAMAZ.', 'Kalıcı Sil', function(){
        window.api.deleteCopItem(STATE.aktifBirimId, copId).then(function(copKutusu){
          STATE.birimVeri.copKutusu = copKutusu;
          showToast('Kayıt kalıcı olarak silindi.');
          renderCopKutusuIcerik(c);
        }).catch(function(err){ alert(err.message); });
      });
    });
  });
}

// Hammadde Cinsleri — "diğer birim"lere özel (örn. Şişirme), Ürün Cinsleri'nden TAMAMEN AYRI bir
// liste. Ok butonlarıyla sıralanabilir, isim değiştirilebilir, silinebilir.
function renderHammaddeListe(){
  var box = document.getElementById('hammadde_liste'); if(!box) return;
  var liste = STATE.birimVeri.hammaddeCinsleri || [];
  if(liste.length === 0){ box.innerHTML = '<div class="note">Henüz tanımlı hammadde yok.</div>'; return; }
  box.innerHTML = liste.map(function(p, i){
    return '<div class="row" style="align-items:center; margin-bottom:8px;">'+
      '<div style="flex:0 0 auto; display:flex; flex-direction:column; gap:2px;">'+
        '<button class="btn ghost small" style="padding:2px 8px;" data-hm-up="'+p.id+'" '+(i===0?'disabled':'')+'>▲</button>'+
        '<button class="btn ghost small" style="padding:2px 8px;" data-hm-down="'+p.id+'" '+(i===liste.length-1?'disabled':'')+'>▼</button>'+
      '</div>'+
      '<div style="flex:1;"><input type="text" data-hm-ad="'+p.id+'" value="'+escapeHtml(p.ad)+'"></div>'+
      '<button class="btn ghost small" data-hm-kaydet="'+p.id+'">Kaydet</button>'+
      (canMutate() ? '<button class="btn danger small" data-hm-sil="'+p.id+'">Sil</button>' : '')+
    '</div>';
  }).join('');
  Array.prototype.forEach.call(box.querySelectorAll('[data-hm-up]'), function(b){
    b.addEventListener('click', function(){
      window.api.reorderHammaddeCinsi(STATE.aktifBirimId, b.dataset.hmUp, 'up').then(function(liste2){
        STATE.birimVeri.hammaddeCinsleri = liste2; renderHammaddeListe();
      }).catch(function(err){ alert(err.message); });
    });
  });
  Array.prototype.forEach.call(box.querySelectorAll('[data-hm-down]'), function(b){
    b.addEventListener('click', function(){
      window.api.reorderHammaddeCinsi(STATE.aktifBirimId, b.dataset.hmDown, 'down').then(function(liste2){
        STATE.birimVeri.hammaddeCinsleri = liste2; renderHammaddeListe();
      }).catch(function(err){ alert(err.message); });
    });
  });
  Array.prototype.forEach.call(box.querySelectorAll('[data-hm-kaydet]'), function(b){
    b.addEventListener('click', function(){
      var id = b.dataset.hmKaydet;
      var yeniAd = box.querySelector('[data-hm-ad="'+id+'"]').value.trim();
      if(!yeniAd){ alert('İsim boş olamaz.'); return; }
      var aciklama = 'Hammadde cinsi yeniden adlandırma: "'+yeniAd+'"';
      mutasyonCagir('updateHammaddeCinsi', [STATE.aktifBirimId, id, yeniAd], aciklama, aktifBirimAdi(), function(liste2, kuyruga){
        if(kuyruga) return;
        STATE.birimVeri.hammaddeCinsleri = liste2; renderHammaddeListe();
      });
    });
  });
  Array.prototype.forEach.call(box.querySelectorAll('[data-hm-sil]'), function(b){
    b.addEventListener('click', function(){
      var id = b.dataset.hmSil;
      var oge = liste.find(function(x){ return x.id === id; });
      showConfirm('Bu hammadde cinsini silmek istediğinize emin misiniz? Geçmiş satın alma/üretim kayıtları etkilenmez.', 'Sil', function(){
        var aciklama = 'Hammadde cinsi silme: '+(oge?oge.ad:'');
        mutasyonCagir('deleteHammaddeCinsi', [STATE.aktifBirimId, id], aciklama, aktifBirimAdi(), function(liste2, kuyruga){
          if(kuyruga) return;
          STATE.birimVeri.hammaddeCinsleri = liste2; renderHammaddeListe();
        });
      });
    });
  });
}
function initHammaddeYonetim(){
  var ekleBtn = document.getElementById('hm_ekle');
  if(!ekleBtn) return;
  ekleBtn.addEventListener('click', function(){
    var ad = document.getElementById('hm_yeni_ad').value.trim();
    if(!ad){ alert('Lütfen bir isim girin.'); return; }
    var aciklama = 'Yeni hammadde cinsi: '+ad;
    mutasyonCagir('addHammaddeCinsi', [STATE.aktifBirimId, ad], aciklama, aktifBirimAdi(), function(liste2, kuyruga){
      if(kuyruga) return;
      STATE.birimVeri.hammaddeCinsleri = liste2;
      document.getElementById('hm_yeni_ad').value = '';
      renderHammaddeListe();
    });
  });
}

